func partitionLabels(_ s: String) -> [Int] {
    let a = Array(s)
    var last: [Character: Int] = [:]
    for (i, c) in a.enumerated() { last[c] = i }
    var result: [Int] = [], start = 0, end = 0
    for (i, c) in a.enumerated() {
        end = max(end, last[c]!)
        if i == end { result.append(end - start + 1); start = i + 1 }
    }
    return result
}
